VALUES (
  '4b2f8000-9e33-46f5-8ae7-673c94796df0'::uuid,
  'Request Multiple Certified Copies of the Death Certificate',
  'Obtain multiple certified copies—typically 10‑15—of the death certificate through the funeral home or county vital‑records office.',
