INSERT INTO task_steps (task_template_id, title, "order", instructions, step_type, communication_helpers, created_at, updated_at)
VALUES (
  'caaaf141-fc72-4539-a5d8-9b2bd1d825e7'::uuid,
  'Call each estate department to request date-of-death statements',
  2,
  'Call each estate department to request date-of-death statements',
  'action'::step_type,
  '{"contactMethod":"phone","phoneScript":"Hello, I''m the executor for the estate of [DECEASED NAME] who passed away on [DATE]. I need to request date-of-death account statements for all accounts held with your institution. What is your process for this and what documentation do you need?","documentsNeeded":["Letters testamentary or trust certificate","Death certificate (certified copy)","List of known account numbers"]}'::jsonb,
