  NOW()
);
INSERT INTO task_steps (task_template_id, title, "order", instructions, step_type, communication_helpers, created_at, updated_at)
VALUES (
  'caaaf141-fc72-4539-a5d8-9b2bd1d825e7'::uuid,
  'Submit formal written request to financial institutions',
  3,
  'Submit formal written request to financial institutions',
  'action'::step_type,
  '{"contactMethod":"mail","emailTemplate":"Subject: Request for Date-of-Death Account Statements - Estate of [DECEASED NAME]\\n\\nDear Estate Department,\\n\\nI am writing to request date-of-death account statements for all accounts held by [DECEASED NAME] (SSN: XXX-XX-XXXX) who passed away on [DATE OF DEATH].\\n\\nAs the court-appointed executor/trustee, I need these statements for estate administration and tax purposes. Please provide statements showing account balances and holdings as of [DATE OF DEATH] for:\\n\\n- All checking and savings accounts\\n- Investment/brokerage accounts\\n- Retirement accounts (401k, IRA, etc.)\\n- Any other accounts or services\\n\\nEnclosed please find:\\n- Certified copy of death certificate\\n- Copy of Letters Testamentary/Trust Certificate\\n- Copy of my identification\\n\\nPlease mail the statements to the address below or advise if you have a secure electronic delivery option.\\n\\nThank you for your assistance.\\n\\nSincerely,\\n[YOUR NAME], Executor/Trustee\\n[MAILING ADDRESS]\\n[PHONE NUMBER]","documentsNeeded":["Executor documentation","Certified death certificate copy","Your photo ID copy"]}'::jsonb,
  NOW(),
  NOW()
);
