  'Create standardized notification letter with deceased information',
  1,
  'Create standardized notification letter with deceased information',
  'action'::step_type,
  '{"contactMethod":"mail","emailTemplate":"Subject: Death Notification - Please Update Records for [DECEASED NAME]\\n\\nDear [Institution Name],\\n\\nI am writing to notify you of the death of [DECEASED NAME] (SSN: XXX-XX-XXXX) who passed away on [DATE OF DEATH].\\n\\nPlease update your records to reflect this death and take the following actions:\\n- Mark all accounts as deceased\\n- Freeze any individual credit lines or accounts\\n- Stop all marketing communications\\n- Convert joint accounts to individual accounts for the surviving account holder\\n\\nI am attaching a certified copy of the death certificate for your records.\\n\\nFor accounts requiring additional documentation, please contact me at [PHONE NUMBER] or [EMAIL ADDRESS].\\n\\nThank you for your prompt attention to this matter.\\n\\nSincerely,\\n[YOUR NAME]\\n[RELATIONSHIP TO DECEASED]\\n[CONTACT INFORMATION]","documentsNeeded":["Certified death certificate copy","Account numbers if available","Your identification"]}'::jsonb,
  NOW(),
  NOW()
);
